('NER', '562', 'Niger', 8, 17.5, 80, 85, 80, 70, 55, array['U','Au','Crude']::text[], 'Nationalised the Somaïr uranium mine from Orano in 2025. Junta aligned with Mali and Burkina Faso; export routes through Benin and Nigeria politically constrained.', array['Disposal of stranded uranium stocks','Border policy with Benin','Gold and oil revenue politics']::text[], '[["2030", "Five-year transition from March 2025"]]'::jsonb, array['metals','energy']::text[], 'africa'),
('CIV', '384', 'Côte d''Ivoire', -5.5, 7.5, 30, 30, 30, 25, 15, array['Au','Mn','Ni','Crude','Gas']::text[], 'Fast-growing gold producer and the main coastal outlet for Mali and Burkina Faso via Abidjan and San Pedro. President re-elected for a fourth term in October 2025.', array['Northern border security with Mali and Burkina Faso','Port capacity at Abidjan and San Pedro']::text[], '[["2030", "Presidential election due"]]'::jsonb, array['metals','energy']::text[], 'africa'),
('BWA', '072', 'Botswana', 24, -22.3, 20, 10, 30, 30, 10, array['Cu','Ag','Ni']::text[], 'Stable democracy with a growing copper belt (Khoemacau, Motheo). Change of government in 2024 passed without disruption.', array['Kalahari copper belt expansion','Trans-Kalahari corridor to Walvis Bay']::text[], '[["2029", "General election due"]]'::jsonb, array['metals']::text[], 'africa'),
