insert into corridors (id, name, mode, risk, origin, destination, km, days, status, path, note, metals, serves, sector, region) values
('lobito', 'Lobito Corridor', 'rail', 2, 'Kolwezi (DRC)', 'Lobito (Angola)', 1300, '8–10', 'Operating, ramping', '[[25.47, -10.72], [23.9, -10.73], [22.35, -10.7], [21, -11.2], [19.92, -11.78], [18.4, -12.1], [16.94, -12.38], [15.73, -12.78], [14.5, -12.7], [13.4, -12.58], [13.55, -12.35]]'::jsonb, 'Concession to Lobito Atlantic Railway (Trafigura, Mota-Engil, Vecturis) with US DFC and EU backing. Fastest route to the Atlantic for Kolwezi copper; capacity still a fraction of road volumes. Zambian spur (Chingola–Jimbe) in financing.', array['Cu','Co']::text[], array['Kamoa-Kakula','Kamoto (KCC)','Mutanda','Tenke Fungurume']::text[], 'metals', 'africa'),
('nsc', 'North–South Corridor', 'road', 3, 'Copperbelt', 'Durban', 3000, '14–28 (round trip)', 'Congested', '[[27.8, -12.25], [28.25, -12.8], [28.68, -13.97], [28.28, -15.42], [28.85, -16.03], [30.3, -17.3], [31.05, -17.83], [30.83, -20.07], [30, -22.22], [29.45, -23.9], [28.05, -26.2], [29.5, -28.3], [31.03, -29.87]]'::jsonb, 'The workhorse route: most Copperbelt cathode and concentrate still goes by truck to Durban through Kasumbalesa, Chirundu and Beitbridge. Each border adds days; Zimbabwe fuel and currency rules add cost.', array['Cu','Co','Zn']::text[], array['Kansanshi','Mopani','Konkola (KCM)','Kinsevere','Kipushi']::text[], 'metals', 'africa'),
('dar', 'Dar es Salaam Corridor', 'mixed', 2, 'Kapiri Mposhi', 'Dar es Salaam', 1860, '7–12', 'Operating; rail revamp pending', '[[28.68, -13.97], [29.5, -13.2], [31, -11], [32.76, -9.3], [33.45, -8.9], [35.7, -7.77], [37.66, -6.82], [39.28, -6.82]]'::jsonb, 'TAZARA rail plus the Tunduma road crossing. China agreed a US$1.4bn revamp of TAZARA; until delivered, trucks dominate. Dar port under DP World since 2023 with improving dwell times.', array['Cu','Co']::text[], array['Kansanshi','Lumwana','Tenke Fungurume']::text[], 'metals', 'africa'),
('beira', 'Beira Corridor', 'mixed', 3, 'Harare', 'Beira', 600, '3–5', 'Operating', '[[31.05, -17.83], [32, -18.5], [32.67, -18.97], [33.48, -19.12], [34.84, -19.84]]'::jsonb, 'Shortest sea access for Zimbabwe PGM and lithium concentrate; Forbes/Machipanda border and Beira draft limits constrain volumes.', array['PGM','Li','Cu']::text[], array['Zimplats (Ngezi)','Bikita','Arcadia']::text[], 'metals', 'africa'),
('walvis', 'Walvis Bay–Ndola–Lubumbashi', 'road', 1, 'Lusaka', 'Walvis Bay', 2500, '10–14', 'Operating, under-used', '[[28.28, -15.42], [27, -16.8], [25.86, -17.85], [24.27, -17.5], [21.5, -17.9], [19.77, -17.93], [18.1, -19.57], [16.65, -20.46], [15.5, -21.9], [14.5, -22.95]]'::jsonb, 'Politically the calmest route out of the Copperbelt, via Kazungula bridge and Namibia''s Trans-Caprivi highway. Longer road leg, but reliable port with spare capacity.', array['Cu','Zn','Ag']::text[], array['Sentinel (Kalumbila)','Kipushi','Khoemacau']::text[], 'metals', 'africa'),
('cbg', 'Sangaredi–Kamsar bauxite rail', 'rail', 2, 'Sangaredi', 'Kamsar', 135, '1', 'Operating', '[[-13.8, 11.1], [-14.05, 11], [-14.28, 10.93], [-14.6, 10.65]]'::jsonb, 'CBG''s dedicated line; shared-use demands and licence revocations elsewhere in Boké are the policy risk.', array['Bx']::text[], array['Sangaredi','Boké (GAC)']::text[], 'metals', 'africa'),
('simandou', 'Trans-Guinean Railway', 'rail', 3, 'Simandou', 'Morebaya', 650, '1–2', 'Commissioned 2025', '[[-8.95, 8.6], [-9.6, 9], [-10.4, 9.4], [-11.2, 9.7], [-12, 9.6], [-12.7, 9.45], [-13.3, 9.3]]'::jsonb, 'New heavy-haul line and port built for Simandou; single-asset dependency makes any failure or political dispute a full-stop for exports.', array['Fe']::text[], array['Simandou']::text[], 'metals', 'africa'),
('mali', 'Mali gold & lithium outlets', 'road', 4, 'Bamako / Kayes', 'Dakar / Abidjan', 1250, '3–6', 'Blockade risk', '[[-11.4, 13], [-11.44, 14.45], [-9.5, 13.8], [-8, 12.65], [-5.68, 11.32], [-5.1, 9.6], [-4.5, 7.5], [-4, 5.3]]'::jsonb, 'Gold leaves Mali mostly by air to Dubai; fuel, consumables and lithium concentrate move by road from Dakar and Abidjan. JNIM blockaded fuel convoys in late 2025, the clearest test of this corridor''s fragility.', array['Au','Li']::text[], array['Loulo-Gounkoto','Fekola','Goulamina','Syama']::text[], 'metals', 'africa'),
('northern', 'Northern Corridor', 'road', 3, 'Mombasa', 'Kampala / Kigali / Goma', 1700, '7–12', 'Operating; sanctions exposure', '[[39.67, -4.05], [37.5, -2.5], [36.82, -1.29], [35.27, 0.51], [34, 0.4], [32.58, 0.35], [31, -0.8], [30.06, -1.94], [29.22, -1.68]]'::jsonb, 'Carries inputs into eastern DRC and 3T and gold out through Uganda and Rwanda. Cargo touching M23-controlled areas or sanctioned intermediaries is a compliance problem.', array['3T','Au']::text[], array['Rubaya','Kibali']::text[], 'metals', 'africa'),
('pgm', 'Bushveld–Richards Bay rail', 'rail', 2, 'Rustenburg', 'Richards Bay / Durban', 700, '2–4', 'Operating; rail reliability', '[[27.2, -25.6], [28.05, -26.2], [29, -27], [29.92, -27.76], [31, -28.4], [32.08, -28.8]]'::jsonb, 'Transnet Freight Rail performance decides PGM concentrate and ferrochrome throughput; private operator access is opening slowly.', array['PGM','Mn']::text[], array['Rustenburg complex','Mogalakwena']::text[], 'metals', 'africa'),
('gabon', 'Transgabonais railway', 'rail', 2, 'Moanda', 'Owendo', 650, '1–2', 'Operating', '[[13.2, -1.55], [12.73, -0.82], [11.93, -0.09], [10.77, -0.18], [9.5, 0.3]]'::jsonb, 'Single line carrying nearly all of Gabon''s manganese; derailments have halted exports for weeks at a time.', array['Mn']::text[], array['Moanda']::text[], 'metals', 'africa'),
('sishen', 'Sishen–Saldanha iron ore line', 'rail', 2, 'Sishen', 'Saldanha Bay', 860, '1–2', 'Operating below capacity', '[[23, -27.8], [21, -29.5], [19.5, -31], [18.3, -32.6], [17.95, -33.03]]'::jsonb, 'Heavy-haul line with chronic locomotive shortages; export volumes have run below nameplate for years.', array['Fe']::text[], array['Sishen']::text[], 'metals', 'africa'),
('hormuz', 'Gulf to Bab el-Mandeb', 'sea', 4, 'Strait of Hormuz', 'Gulf of Aden', 2400, '5–7', 'Open with restrictions', '[[56.3, 26.4], [57.5, 24.5], [58.5, 22], [57, 18.5], [52, 14.5], [48, 12.5], [43.5, 12.3]]'::jsonb, 'The tanker lane carrying about a fifth of world oil and LNG. Closed from late February 2026 by the US–Israel conflict with Iran; reopened to commercial traffic in designated lanes on 17 April 2026 under a truce, with a US blockade on Iranian ports continuing. Flows slow to normalise.', array['Crude','LNG','Prod','LPG']::text[], '{}'::text[], 'energy', 'all'),
('suez', 'Red Sea – Suez route', 'sea', 3, 'Bab el-Mandeb', 'Port Said', 2200, '4–6', 'Recovering, Houthi threat', '[[43.3, 12.6], [41.5, 15.5], [39, 20], [36, 24.5], [34, 27.5], [32.8, 29.2], [32.55, 29.97], [32.3, 31.26], [31.8, 32.4]]'::jsonb, 'September 2026 Suez transits were 1,228 (second month above 100m dwt) but still 39% below pre-crisis levels; Bab el-Mandeb 47% below. Houthis attacked a containership off Yemen on 7 October 2026 and announced a blockade of Saudi Red Sea ports. Most Suez tankers carry Russian crude to India.', array['Crude','Prod','LNG','Bunk']::text[], array['Ain Sukhna terminal']::text[], 'energy', 'all'),
('cape', 'Cape of Good Hope diversion', 'sea', 1, 'Gulf of Aden', 'South Atlantic', 11000, '+10–14 vs Suez', 'Open', '[[43.5, 11.5], [50.5, 0], [42, -14], [36.5, -27], [27, -35.5], [18.5, -36], [10, -26], [4, -8]]'::jsonb, 'The default alternative when the Red Sea is unsafe; adds roughly two weeks and raises bunker consumption. Carriers began switching back to Suez through 2026.', array['Crude','Prod','LNG','Bunk']::text[], '{}'::text[], 'energy', 'all'),
('gibraltar', 'Mediterranean – Atlantic lane', 'sea', 1, 'Central Mediterranean', 'Strait of Gibraltar', 1600, '3–4', 'Open', '[[13, 34.5], [10, 36.5], [3, 37.5], [-2, 36.2], [-5.6, 35.95], [-9, 36]]'::jsonb, 'Libyan and Algerian crude, Algerian LNG and Mediterranean products to the Atlantic; Tangier Med bunkering at the exit.', array['Crude','LNG','Prod','Bunk']::text[], array['Arzew LNG & export complex','Tangier Med bunkering hub']::text[], 'energy', 'all'),
('guinea', 'Gulf of Guinea export lane', 'sea', 2, 'Bonny / Lagos', 'Cape route and Atlantic', 5000, '8–12', 'Open, piracy watch', '[[7, 4.2], [3.4, 6.2], [0, 3], [-4, -4], [-3, -18], [8, -30], [18.5, -36]]'::jsonb, 'West African crude and Dangote products to Europe, Asia and the US Gulf; piracy and kidnapping risk concentrated off the Niger Delta.', array['Crude','Prod','LNG']::text[], array['Bonga FPSO','Escravos terminal','Bonny Island LNG','Dangote Refinery (Lekki)']::text[], 'energy', 'africa'),
('eacop', 'EACOP (East African Crude Oil Pipeline)', 'pipeline', 2, 'Hoima (Uganda)', 'Tanga (Tanzania)', 1443, '—', '82% built; first oil targeted 2026', '[[31.35, 1.43], [31, 0.5], [30.7, -1.1], [31.5, -2], [32.9, -3.2], [34.5, -4], [36.5, -4.6], [38.2, -5], [39.1, -5.07]]'::jsonb, 'Heated 216,000 b/d line from Lake Albert to Tanga; 82% complete in April 2026 with first oil targeted for the second half of 2026. Financing and litigation pressure from campaigners continues.', array['Crude']::text[], array['Tilenga & Kingfisher (Lake Albert)','Tanga crude export terminal']::text[], 'energy', 'africa'),
('chadcam', 'Chad–Cameroon pipeline', 'pipeline', 2, 'Doba', 'Kribi', 1070, '—', 'Operating', '[[16.85, 8.65], [15, 7.5], [13, 5.5], [11.5, 4], [9.9, 2.95]]'::jsonb, 'Chad''s only export route; tariff disputes between N''Djamena and Yaoundé and the 2023 nationalisation of Exxon''s stake are the live issues.', array['Crude']::text[], array['Doba fields','Kribi (Kome Kribi 1) terminal']::text[], 'energy', 'africa'),
('transmed', 'Transmed gas pipeline', 'pipeline', 1, 'Hassi R''Mel', 'Sicily', 2500, '—', 'Operating', '[[3.27, 32.93], [6.5, 33.8], [8.5, 34.5], [10.5, 37], [12.6, 37.5]]'::jsonb, 'Largest Algerian gas route to Italy via Tunisia; volumes rose after Europe cut Russian supply.', array['Gas']::text[], array['Hassi R''Mel']::text[], 'energy', 'africa'),
('medgaz', 'Medgaz pipeline', 'pipeline', 1, 'Beni Saf', 'Almería', 760, '—', 'Operating', '[[3.27, 32.93], [0, 34.5], [-1.4, 35.3], [-2.4, 36.8]]'::jsonb, 'Direct Algeria–Spain line; the Maghreb–Europe line via Morocco has been shut since 2021 over the Algeria–Morocco dispute.', array['Gas']::text[], array['Hassi R''Mel']::text[], 'energy', 'africa'),
('greenstream', 'Greenstream pipeline', 'pipeline', 2, 'Mellitah', 'Gela (Sicily)', 520, '—', 'Operating', '[[12.75, 32.9], [13.3, 35], [14.25, 37.07]]'::jsonb, 'Libya''s gas export line to Italy; exposed to the same western-Libya instability as Zawiya.', array['Gas']::text[], array['Mellitah complex']::text[], 'energy', 'africa'),
('sumed', 'SUMED pipeline', 'pipeline', 2, 'Ain Sukhna', 'Sidi Kerir', 320, '—', 'Operating', '[[32.35, 29.6], [31.5, 30.3], [30.5, 30.9], [29.6, 31.1]]'::jsonb, 'Bypasses the Suez Canal for crude; throughput rises and falls with Red Sea security and Gulf flows.', array['Crude']::text[], array['Ain Sukhna terminal','Sidi Kerir terminal']::text[], 'energy', 'africa'),
('delta', 'Niger Delta pipelines (TNP / TFP)', 'pipeline', 4, 'Delta fields', 'Bonny and Forcados terminals', 400, '—', 'Sabotage-prone', '[[6.4, 5.5], [6.9, 5.1], [7, 4.9], [7.17, 4.43]]'::jsonb, 'Trans Niger and Trans Forcados lines: theft, sabotage and explosions (March 2025 TNP blast) regularly halt Bonny Light and Forcados exports.', array['Crude']::text[], array['Forcados terminal','Bonny Island LNG']::text[], 'energy', 'africa'),
('nile', 'Greater Nile pipeline (South Sudan–Port Sudan)', 'pipeline', 4, 'Palouge / Unity', 'Port Sudan (Bashayer)', 1600, '—', 'Reduced flows; war zone', '[[32.5, 10.4], [32.7, 13.2], [33, 15.6], [35, 18], [37.2, 19.2]]'::jsonb, 'South Sudan''s only outlet runs through Sudan''s civil war; a 2024 rupture halted exports for months and flows have been partial since.', array['Crude']::text[], array['Palouge & Unity fields']::text[], 'energy', 'africa'),
('nigerbenin', 'Niger–Benin pipeline', 'pipeline', 4, 'Agadem', 'Sèmè-Kpodji', 2000, '—', 'Intermittent', '[[12.9, 16.9], [9, 15], [5, 13], [3, 9.5], [2.6, 6.4]]'::jsonb, 'Niger''s only crude export route, opened 2024. Benin blocked loadings during the 2024 border dispute and attacks on the line have interrupted flows since.', array['Crude']::text[], array['Agadem fields']::text[], 'energy', 'africa'),
('kpc', 'Kenya Pipeline (Mombasa–Nairobi–Eldoret)', 'pipeline', 2, 'Mombasa', 'Eldoret / Kisumu', 900, '—', 'Operating', '[[39.65, -4.05], [37.5, -2.5], [36.82, -1.29], [36, -0.5], [35.27, 0.51]]'::jsonb, 'Carries imported refined products inland for Kenya, Uganda, Rwanda and eastern DRC; capacity constraints push volumes onto trucks.', array['Prod']::text[], array['Mombasa oil terminal (KOT)']::text[], 'energy', 'africa'),
('sharara', 'Sharara–Zawiya crude line', 'pipeline', 4, 'Sharara', 'Zawiya', 700, '—', 'Shut since 14 Aug 2026 (verify)', '[[12.5, 26.6], [12.6, 28.2], [12.6, 29.6], [12.65, 31.2], [12.72, 32.8]]'::jsonb, 'Libya''s most-interrupted pipeline: shut by blockades repeatedly and again on 14 August 2026, cutting national output by about a fifth and triggering force majeure at Zawiya.', array['Crude']::text[], array['Sharara field','El Feel (Elephant) field','Zawiya terminal & refinery']::text[], 'energy', 'africa'),
('panama', 'Panama Canal', 'sea', 2, 'Colón (Atlantic)', 'Balboa (Pacific)', 82, '0.5–1', 'Normal transits; water-dependent', '[[-79.92, 9.37], [-79.88, 9.3], [-79.8, 9.22], [-79.7, 9.15], [-79.62, 9.07], [-79.57, 8.98], [-79.52, 8.88]]'::jsonb, 'About 5% of world seaborne trade. The 2023–24 drought cut daily transits from 36 to 24 and imposed draft limits; levels recovered in 2024–25. LNG and LPG carriers from the US Gulf to Asia are the most price-sensitive users.', array['Crude','Prod','LNG','LPG','Cu']::text[], '{}'::text[], 'all', 'all'),
('magellan', 'Strait of Magellan / Cape Horn', 'sea', 1, 'Atlantic', 'Pacific', 570, '1–2', 'Open; weather-limited', '[[-67.5, -52.5], [-69, -52.8], [-70.5, -53.3], [-72, -53.6], [-73.5, -53.3], [-74.8, -52.6]]'::jsonb, 'Route for vessels too large for the canal and for Vaca Muerta crude heading to the Pacific; pilotage compulsory, winter weather closes windows.', array['Crude','Fe']::text[], '{}'::text[], 'all', 'americas'),
('lasbambas', 'Southern mining corridor (Las Bambas road)', 'road', 4, 'Las Bambas (Apurímac)', 'Matarani', 450, '2–3', 'Blocked several times a year', '[[-72.33, -14.07], [-72.1, -14.3], [-71.85, -14.55], [-71.6, -14.9], [-71.5, -15.4], [-71.45, -16], [-71.55, -16.5], [-72.1, -17]]'::jsonb, 'Unpaved stretches through Chumbivilcas and Espinar communities who block the road over dust, compensation and land; MMG has lost months of shipments in bad years. Informal miners joined the blockades in 2025.', array['Cu']::text[], array['Las Bambas']::text[], 'metals', 'americas'),
('jama', 'Lithium triangle roads (Paso de Jama)', 'road', 2, 'Olaroz / Hombre Muerto', 'Antofagasta', 550, '2–3', 'Operating; winter closures', '[[-67.08, -25.4], [-66.8, -24.5], [-66.72, -23.5], [-67.03, -23.23], [-67.8, -23.1], [-68.6, -23.2], [-69.6, -23.4], [-70.4, -23.65]]'::jsonb, 'Carbonate from Jujuy and Catamarca crosses the Andes at 4,200 m to Chilean ports; snow closures and customs at Jama add days.', array['Li']::text[], array['Olaroz / Cauchari','Fénix (Hombre Muerto)']::text[], 'metals', 'americas'),
('carajas', 'Carajás railway (EFC)', 'rail', 1, 'Carajás', 'Ponta da Madeira', 892, '1–2', 'Operating', '[[-50.17, -6.07], [-49.2, -5.6], [-48.2, -5.2], [-47.2, -4.6], [-46.2, -3.8], [-45.2, -3.1], [-44.37, -2.57]]'::jsonb, 'Vale''s heavy-haul line moving about 180 Mt/y; occasional blockades by communities and the MST, and a court-ordered stoppage in 2024 over indigenous consultation.', array['Fe','Cu']::text[], array['Carajás (Serra Norte / S11D)','Salobo','Sossego']::text[], 'metals', 'americas'),
('efvm', 'Vitória–Minas railway', 'rail', 1, 'Itabira / Minas Gerais', 'Tubarão (Vitória)', 905, '1', 'Operating', '[[-43.8, -19.6], [-43.2, -19.6], [-42.4, -19.4], [-41.6, -19.3], [-40.9, -19.5], [-40.25, -20.28]]'::jsonb, 'Vale''s southern system; concession renewed to 2057 with investment obligations.', array['Fe']::text[], '{}'::text[], 'metals', 'americas'),
('minasrio', 'Minas-Rio slurry pipeline', 'pipeline', 1, 'Conceição do Mato Dentro', 'Açu port', 529, '3', 'Operating', '[[-43.7, -18.9], [-43, -19.3], [-42.2, -19.9], [-41.5, -20.8], [-41, -21.8]]'::jsonb, 'Longest iron ore slurry pipeline in the world; pipeline leaks in 2018 shut the operation for most of a year.', array['Fe']::text[], array['Minas-Rio']::text[], 'metals', 'americas'),
('norperuano', 'Oleoducto Norperuano', 'pipeline', 3, 'Loreto (Block 192 / 8)', 'Bayóvar', 1100, '7–10', 'Intermittent; sabotage and spills', '[[-75.3, -4.5], [-76.3, -4.7], [-77.3, -5.3], [-78.3, -5.6], [-79.3, -5.7], [-80.3, -5.8], [-81.05, -5.8]]'::jsonb, 'Petroperú''s 1970s line across the Amazon and Andes; dozens of spills, many from deliberate cuts by communities seeking compensation. Volumes are small but politically loud.', array['Crude']::text[], '{}'::text[], 'energy', 'americas'),
('canolimon', 'Caño Limón–Coveñas pipeline', 'pipeline', 3, 'Caño Limón (Arauca)', 'Coveñas', 780, '4–6', 'Attacked repeatedly', '[[-71.3, 6.9], [-72.2, 7.3], [-72.9, 7.65], [-73.5, 7.95], [-74.2, 8.3], [-75.1, 9], [-75.68, 9.4]]'::jsonb, 'Bombed more than 1,000 times by the ELN since the 1980s; the Catatumbo offensive of January 2025 brought renewed attacks and a state of emergency.', array['Crude']::text[], array['Caño Limón']::text[], 'energy', 'americas'),
('sote', 'SOTE and OCP pipelines', 'pipeline', 3, 'Lago Agrio', 'Balao (Esmeraldas)', 500, '2–3', 'Landslide-prone; repeated force majeure', '[[-76.9, 0.1], [-77.6, 0.1], [-78.3, 0], [-78.85, 0.3], [-79.35, 0.8], [-79.65, 0.99]]'::jsonb, 'Both trunk lines cross the Coca river gorge, where regressive erosion since 2020 has repeatedly broken them. The March 2025 rupture spilled into the Esmeraldas river and forced a force majeure on exports.', array['Crude']::text[], array['Esmeraldas refinery']::text[], 'energy', 'americas'),
('oldelval', 'Oldelval and VMOS (Vaca Muerta export system)', 'pipeline', 1, 'Allen (Neuquén)', 'Bahía Blanca / Punta Colorada', 600, '2–3', 'Expanding', '[[-68.7, -38.1], [-67.6, -38.5], [-66.4, -38.8], [-65.2, -39.1], [-64, -39], [-63, -38.9], [-62.28, -38.78]]'::jsonb, 'Oldelval''s Duplicar expansion lifted capacity in 2025; the VMOS line to a new deepwater terminal at Punta Colorada (Río Negro) is due in 2027 and would allow VLCC loadings.', array['Crude']::text[], array['Vaca Muerta (Loma Campana)','Punta Colorada terminal (VMOS)']::text[], 'energy', 'americas'),
('gasbol', 'Bolivia–Brazil gas pipeline (GASBOL)', 'pipeline', 2, 'Río Grande (Santa Cruz)', 'São Paulo', 3150, '—', 'Declining Bolivian supply', '[[-63.2, -17.8], [-61, -18], [-58.8, -19.2], [-57.65, -19], [-55.5, -20.5], [-52.5, -21.5], [-49.5, -22.5], [-47.5, -23.2], [-46.5, -23.5]]'::jsonb, 'Bolivian volumes have fallen with field decline; Argentina has begun sending Vaca Muerta gas to Brazil through Bolivia in reverse flow.', array['Gas']::text[], array['Margarita–Huacaya']::text[], 'energy', 'americas'),
('orinoco', 'Orinoco Belt to Jose', 'pipeline', 4, 'Faja del Orinoco', 'Jose terminal', 200, '1', 'Sanctions-constrained', '[[-63.5, 8.5], [-64, 8.9], [-64.4, 9.5], [-64.7, 10.1]]'::jsonb, 'Diluted crude moves by pipeline to the Jose upgraders and loading berths; throughput depends on naphtha imports, power and OFAC licences.', array['Crude']::text[], array['Orinoco Belt (Faja)','Jose terminal']::text[], 'energy', 'americas'),
