('transpac', 'Trans-Pacific concentrate lane', 'sea', 1, 'Antofagasta / Matarani / Callao', 'China, Japan, Korea', 17000, '30–40', 'Open', '[[-70.4, -23.65], [-72.1, -17], [-77.15, -12.05], [-77.6, -11.57], [-85, -10], [-100, -6], [-115, -2]]'::jsonb, 'Most Chilean and Peruvian concentrate goes to Chinese smelters; Chancay''s direct Shanghai service cut transit to 23 days.', array['Cu','Zn','Li']::text[], array['Escondida','Las Bambas','Cerro Verde','Antamina']::text[], 'metals', 'americas'),
('carib', 'Caribbean crude lane', 'sea', 3, 'Jose / Puerto La Cruz', 'US Gulf Coast and Asia', 3200, '5–7', 'Sanctions and interdiction risk', '[[-64.7, 10.1], [-66, 12.5], [-70, 15.5], [-73.5, 18.5], [-74.2, 20.2], [-78, 22.5], [-84, 24.5], [-90, 27.5]]'::jsonb, 'Venezuelan cargoes to the US run under OFAC licences; the shadow fleet heads east. US naval activity in the southern Caribbean from late 2025 added interdiction risk for unlicensed liftings.', array['Crude','Prod']::text[], array['Jose terminal']::text[], 'energy', 'americas')
