insert into events (date, iso, lon, lat, type, severity, metals, title, summary, corridors, status, sector, region) values
('2024-03-04', 'ZWE', 31.05, -17.83, 'sanctions', 2, array['Li','PGM','Au']::text[], 'US replaces Zimbabwe sanctions programme with targeted designations', 'OFAC lifted the country-wide programme and designated President Mnangagwa and associates under Global Magnitsky. Compliance screening of state-linked counterparties remains necessary.', array['beira','nsc']::text[], 'seed', 'metals', 'africa'),
('2024-08-27', 'BFA', 0.8, 12.2, 'nationalisation', 3, array['Au']::text[], 'Burkina Faso takes Boungou and Wahgnion gold mines into state company SOPAMIB', 'Formal nationalisation of two producing mines under the 2024 mining code, with limited compensation. Template for Sahel resource nationalism.', '{}'::text[], 'seed', 'metals', 'africa'),
('2024-09-15', 'ZMB', 28.28, -15.42, 'infrastructure', 2, array['Cu']::text[], 'Kariba drought cuts Zambian hydropower; mines import power and run diesel', 'Power rationing raised copper unit costs through the 2024-25 dry season and delayed expansions.', array['nsc','dar']::text[], 'seed', 'metals', 'africa'),
('2024-11-07', 'MLI', -8, 12.65, 'regulatory', 3, array['Au']::text[], 'Resolute Mining CEO detained in Bamako', 'Released after Resolute agreed a US$160m settlement with the government; signalled that executives are leverage in code renegotiations.', array['mali']::text[], 'seed', 'metals', 'africa'),
('2024-11-20', 'MOZ', 32, -25.44, 'unrest', 3, array['Mn','PGM']::text[], 'Post-election protests close Ressano Garcia border repeatedly', 'Opposition protests blocked the N4 corridor and Maputo port access through January 2025; South African chrome, ferrochrome and magnetite rerouted to Richards Bay.', array['nsc']::text[], 'seed', 'metals', 'africa'),
('2024-12-15', 'MLI', -7.6, 11.9, 'milestone', 1, array['Li']::text[], 'Goulamina ships first lithium concentrate', 'Ganfeng-operated mine began production; road export via Côte d''Ivoire.', array['mali']::text[], 'seed', 'metals', 'africa'),
('2025-01-14', 'MLI', -11.4, 13, 'regulatory', 4, array['Au']::text[], 'Barrick suspends Loulo-Gounkoto after Mali seizes gold stock', 'About three tonnes of gold removed from site by authorities; operations halted pending resolution of the dispute over the 2023 code.', array['mali']::text[], 'seed', 'metals', 'africa'),
('2025-01-27', 'COD', 29.22, -1.68, 'conflict', 4, array['3T','Au']::text[], 'M23/AFC captures Goma; Bukavu falls in February', 'Rwandan-backed rebels took the two largest cities in the Kivus. Northern Corridor cargo into eastern DRC and 3T exports now pass through rebel-taxed territory.', array['northern']::text[], 'seed', 'metals', 'africa'),
('2025-02-20', 'RWA', 30.06, -1.94, 'sanctions', 3, array['3T','Au']::text[], 'US sanctions Rwandan minister Kabarebe and M23 spokesman', 'Treasury designations for support to M23 and illicit mineral trade; EU followed with its own listings. Due-diligence burden rises on Kigali-routed cargo.', array['northern']::text[], 'seed', 'metals', 'africa'),
('2025-02-22', 'COD', 25.47, -10.72, 'export-control', 4, array['Co']::text[], 'DRC suspends all cobalt exports for four months', 'ARECOMS halted cobalt hydroxide exports to lift prices after a 2024 collapse. Stocks built at mines and at Durban and Dar es Salaam.', array['lobito','nsc','dar']::text[], 'seed', 'metals', 'africa'),
('2025-04-12', 'GAB', 9.45, 0.39, 'political', 2, array['Mn']::text[], 'Oligui Nguema elected president of Gabon', 'Coup leader of 2023 won the election with about 90% of the vote; policy continuity on manganese beneficiation expected.', array['gabon']::text[], 'seed', 'metals', 'africa'),
('2025-05-18', 'COD', 25.33, -10.75, 'infrastructure', 3, array['Cu']::text[], 'Seismic activity halts Kakula underground mine', 'Ivanhoe suspended underground operations at Kakula and cut 2025 guidance; partial restart over following months.', array['lobito']::text[], 'seed', 'metals', 'africa'),
('2025-06-10', 'ZWE', 31.05, -17.83, 'export-control', 3, array['Li']::text[], 'Zimbabwe sets lithium concentrate export ban from January 2027', 'Government confirmed a deadline for in-country processing; Chinese operators accelerate sulphate plant construction.', array['beira']::text[], 'seed', 'metals', 'africa'),
('2025-06-16', 'MLI', -11.4, 13, 'nationalisation', 4, array['Au']::text[], 'Mali court places Loulo-Gounkoto under provisional state administration', 'Court-appointed administrator took control with authority to restart operations and sell gold.', array['mali']::text[], 'seed', 'metals', 'africa'),
('2025-06-19', 'NER', 7.3, 18.75, 'nationalisation', 4, array['U']::text[], 'Niger nationalises Somaïr uranium mine', 'Orano''s majority stake expropriated; stockpiled yellowcake stranded by closed Benin border. Arbitration initiated.', '{}'::text[], 'seed', 'metals', 'africa'),
('2025-06-21', 'COD', 25.47, -10.72, 'export-control', 3, array['Co']::text[], 'DRC extends cobalt export suspension by three months', 'Extension to late September 2025; traders report hydroxide stocks of several months of demand.', array['lobito','nsc','dar']::text[], 'seed', 'metals', 'africa'),
('2025-06-27', 'COD', 29.22, -1.68, 'political', 2, array['3T','Au','Cu']::text[], 'DRC and Rwanda sign US-brokered peace agreement in Washington', 'Agreement paired with a prospective US–DRC minerals partnership; implementation and M23 withdrawal unresolved.', array['northern']::text[], 'seed', 'metals', 'africa'),
