('2025-09-21', 'GIN', -13.7, 9.52, 'political', 2, array['Bx','Fe']::text[], 'Guinea approves new constitution by referendum', 'Cleared the path for the junta leader to stand in the December election.', array['cbg','simandou']::text[], 'seed', 'metals', 'africa'),
