insert into forecasts (question, probability, resolves_on, criteria, rationale, sector, region) values
('DRC cobalt export quota regime still in force on 30 June 2027', 72, '2027-06-30', 'Resolves YES if ARECOMS quotas (or a successor volume cap) remain legally in force on the date.', 'The regime is working for Kinshasa: prices recovered and the state gained allocation power. Lifting it would need a price collapse or a deal with China. Risk is quota revision rather than removal.', 'metals', 'africa'),
('Lobito Corridor moves more than 500 kt of copper and cobalt in calendar 2027', 35, '2028-02-28', 'Resolves YES on operator or DRC customs data showing combined Cu + Co volumes above 500,000 t for 2027.', 'Volumes are rising but rolling stock, Dilolo customs and mine-side loading remain bottlenecks. Most cargo still trucks to Durban and Dar.', 'metals', 'africa'),
('Zimbabwe enforces the lithium concentrate export ban by 31 March 2027', 58, '2027-03-31', 'Resolves YES if concentrate exports are prohibited in practice (no general exemptions) by the date; a blanket delay resolves NO.', 'Government has held the line publicly and Chinese operators are building sulphate plants, but a weak lithium price makes a phased delay plausible.', 'metals', 'africa'),
('Loulo-Gounkoto operates without a new state-ordered stoppage through 30 June 2027', 55, '2027-06-30', 'Resolves NO if Malian authorities suspend operations, seize output or reinstate administration for more than 14 days.', 'A settlement was reported in late 2025, but the junta has shown it will reopen terms when revenue needs rise. Status should be verified before use.', 'metals', 'africa'),
('Guinea revokes at least one more bauxite mining licence held by a foreign operator by 30 June 2027', 62, '2027-06-30', 'Resolves YES on an official revocation of a producing or advanced bauxite licence.', 'Refinery commitments remain unmet across the sector and the new administration has used revocation as leverage repeatedly.', 'metals', 'africa'),
('M23/AFC withdraws from Goma by 30 June 2027', 15, '2027-06-30', 'Resolves YES if Congolese state authority is restored in Goma under the Washington or Doha framework.', 'Agreements exist on paper; neither side has moved on the ground. Withdrawal would require a security guarantee Kinshasa cannot yet provide.', 'metals', 'africa'),
('Burkina Faso nationalises an additional foreign-owned gold mine by 30 June 2027', 45, '2027-06-30', 'Resolves YES on transfer of majority control of a producing mine to SOPAMIB or another state entity.', 'The state is cash-constrained and the 2024 code enables it, but it also needs operators who can run the remaining mines.', 'metals', 'africa'),
('Kasumbalesa truck queues exceed five days in any month of H1 2027', 50, '2027-07-15', 'Resolves YES on credible reporting (industry body, major operator or press) of average clearance times above five days in any calendar month.', 'Record copper volumes meet unchanged border capacity. Lobito and Dar relief is real but gradual.', 'metals', 'africa'),
('South Africa''s Transnet rail volumes exceed 170 Mt in FY2026/27', 35, '2027-06-30', 'Resolves YES on Transnet''s reported annual freight rail tonnage.', 'Recovery from the 2023 trough is slow; locomotive availability and cable theft persist. Private slots help at the margin.', 'metals', 'africa'),
('Angola''s 2027 election passes without protests that close Lobito port for more than 48 hours', 80, '2027-09-30', 'Resolves NO if the port or railway terminal is shut by unrest for over two consecutive days in the election period.', '2025 fuel protests were serious but concentrated in Luanda; Lobito''s political economy depends on the corridor staying open.', 'metals', 'africa'),
('EACOP loads its first export cargo at Tanga by 31 March 2027', 60, '2027-03-31', 'Resolves YES on an official or press-confirmed first crude lifting from Tanga.', '82% complete in April 2026 with first oil targeted for late 2026; commissioning of a heated line and the Tilenga ramp-up usually slip a quarter or two.', 'energy', 'africa'),
('Strait of Hormuz suffers another closure of seven or more days before 30 June 2027', 25, '2027-06-30', 'Resolves YES if commercial tanker transits stop or fall below 20% of normal for seven consecutive days.', 'The April 2026 reopening holds but the underlying deal is unfinished and the US blockade continues; a breakdown is plausible but both sides have strong reasons to keep the lane open.', 'energy', 'africa'),
('Suez Canal monthly transits exceed 1,500 in any month of H1 2027', 35, '2027-07-15', 'Resolves YES on Suez Canal Authority or Lloyd''s List data showing more than 1,500 transits in a calendar month.', 'September 2026 was 1,228 and 39% below pre-crisis; recovery is real but Houthi threats returned in July and October 2026.', 'energy', 'africa'),
('Libya declares force majeure at a major field or terminal again before 30 June 2027', 80, '2027-06-30', 'Resolves YES on an NOC force majeure declaration covering any field or terminal above 100,000 b/d.', 'Two separate shutdowns in August and September 2026 and no resolution of the political split; the base rate is several per year.', 'energy', 'africa'),
('Mozambique LNG reports no new force majeure or security suspension through 30 June 2027', 70, '2027-06-30', 'Resolves NO on any announced suspension of site activities of 14 days or more.', 'Restart in January 2026 followed security assurances; Cabo Delgado violence persists at lower levels and the site is heavily guarded.', 'energy', 'africa'),
('Niger–Benin pipeline exports flow without a stoppage longer than 30 days in H1 2027', 45, '2027-07-15', 'Resolves NO on any reported interruption of loadings at Sèmè exceeding 30 consecutive days.', 'Benin–Niger relations remain poor and the line has been attacked; CNPC has strong incentives to keep cargoes moving.', 'energy', 'africa'),
('Dangote refinery exports average more than 150,000 b/d of refined products in Q1 2027', 50, '2027-04-30', 'Resolves YES on Kpler/Vortexa or NNPC data showing average product exports above 150,000 b/d for the quarter.', '700,000 b/d tests in mid-2026 and domestic demand of roughly 450,000 b/d leave room for large exports, but crude sourcing and maintenance cycles are unproven.', 'energy', 'africa'),
('Cobre Panamá resumes commercial copper production by 31 December 2027', 40, '2027-12-31', 'Resolves YES on First Quantum reporting concentrate shipments from the mine under a new agreement with the government.', 'Both sides want the revenue, but the 2023 ruling, a new contract needing legislative approval and the arbitration make a two-year timeline tight.', 'metals', 'americas'),
('The Las Bambas corridor is blocked for 14 or more consecutive days before 30 June 2027', 65, '2027-06-30', 'Resolves YES on MMG or Peruvian government confirmation of a continuous road blockade of 14+ days affecting concentrate transport.', 'Blockades of this length happened in most recent years; the REINFO dispute and a new government''s early months are classic triggers.', 'metals', 'americas'),
('Venezuelan crude exports to the United States exceed 300,000 b/d in any month of H1 2027', 55, '2027-07-15', 'Resolves YES on EIA or Kpler data showing US imports of Venezuelan crude above 300,000 b/d for any calendar month.', 'Licences have widened since early 2026 and Gulf refiners want the heavy barrels, but upgrader throughput and politics in Caracas are unreliable (desk to update as the picture clarifies).', 'energy', 'americas'),
('Panama Canal keeps average daily transits at 34 or more through the 2027 dry season (to 30 April 2027)', 75, '2027-04-30', 'Resolves NO if the Canal Authority announces transit caps below 34 per day or draft limits below 44 ft for 14+ days.', 'Gatún Lake levels recovered in 2024–25 and the authority now manages water more conservatively; a strong El Niño would be the risk.', 'all', 'americas'),
('Argentina loads its first LNG export cargo by 31 December 2027', 55, '2027-12-31', 'Resolves YES on a confirmed LNG cargo loaded from an Argentine FLNG unit.', 'The Hilli Episeyo charter and pipeline works are on a 2027 schedule; floating units slip less than onshore plants, but Argentine permitting and gas supply contracts could add a quarter or two.', 'energy', 'americas'),
('Bolivia''s legislature ratifies at least one YLB lithium extraction contract by 30 June 2027', 35, '2027-06-30', 'Resolves YES on legislative approval of the CBC, Uranium One or any successor DLE contract.', 'The new government wants investment, but the contracts were negotiated by its predecessor and Potosí civic groups oppose them.', 'metals', 'americas'),
('Petrobras announces a commercial discovery on the Equatorial Margin by 31 December 2027', 35, '2027-12-31', 'Resolves YES on a Petrobras declaration of commerciality or a discovery notice describing hydrocarbons in commercial quantities from FZA-M-59 or an adjacent well.', 'The geology is promising by analogy with Guyana, but one well rarely proves a play and drilling only began in late 2025.', 'energy', 'americas');
insert into briefings (id, date, title, lede, sections) values
('000', '2026-11-02', 'Baseline brief: where African metals risk stands', 'Issue 00 sets the desk''s starting view across the five flows this platform tracks. Later issues report changes against this baseline.', '[["Copperbelt exports", "The DR Congo\u2013Zambia copper belt is producing at record rates and the roads out have not grown with it. Kasumbalesa clears tens of thousands of trucks a month and backs up whenever Congolese export paperwork changes. The Lobito railway is the structural fix, but it is still a small share of volume; Dar es Salaam and Walvis Bay absorb the rest of the overflow. The cobalt quota regime introduced in October 2025 is now the single largest policy variable for anyone holding hydroxide: allocations are political, and revisions can arrive with days of notice."], ["Sahel gold", "Mali, Burkina Faso and Niger have moved from renegotiation to direct control. The Loulo-Gounkoto episode showed a government willing to seize bullion and detain executives to force terms; Burkina Faso''s SOPAMIB and Niger''s Soma\u00efr nationalisation are the same logic. The operational risk is now as serious as the legal one: the 2025 fuel blockade of Bamako demonstrated that JNIM can choke the road corridors from Dakar and Abidjan, and every mine in the region runs on trucked diesel."], ["Guinea", "Simandou has begun shipping and the bauxite sector has been reshaped by licence revocations. The new civilian-labelled administration is the same leadership that revoked GAC''s licence, so expect continued use of permits as leverage for local refining. Single-asset dependency on the Trans-Guinean railway is the physical risk."], ["Southern Africa processing", "Zimbabwe''s lithium concentrate ban (January 2027) and Gabon''s planned manganese ore ban (2029) share a theme with Namibia''s existing rules: governments want processing on-shore and are prepared to lose export volume to get it. South Africa''s constraint is different: it is physical, in Transnet''s rail and ports, and it ripples north because Durban is the default outlet for the Copperbelt."], ["Eastern DRC and compliance", "M23 holds Goma and Bukavu and taxes the coltan trade; the Washington agreement has not changed that on the ground. Cargo through Rwanda and Uganda now carries a sanctions and traceability burden that did not exist two years ago. For a trader, the exposure is documentary as much as physical."], ["What we are watching to year-end", "Cobalt quota allocations for 2027; the aftermath of Zambia''s August election; whether Mali''s settlement with Barrick holds; freight costs if the Hormuz disruption persists into the northern winter; and any Transnet concession awards. Our open forecast calls on each are on the Forecasts tab."]]'::jsonb),
('E00', '2026-11-02', 'Energy baseline: Africa, the Mediterranean and the lanes between', 'The energy desk''s starting view across the flows this engine tracks: Gulf and Red Sea sea lanes, North African gas and crude, the Gulf of Guinea, and East Africa''s new export projects.', '[["Sea lanes", "2026 rewrote the risk map. The Iran conflict closed Hormuz from late February and reopened it in designated lanes from 17 April under a truce that is still unfinished. The Red Sea recovered through the summer, then Houthi threats returned in July and an attack off Yemen in October. Suez transits in September were the best since the crisis began and still 39% below normal. For a trader the practical result is two freight regimes, Suez and Cape, that can swap within a week."], ["Libya", "The country produces 1.2 million b/d when nobody closes a valve, and in 2026 somebody did twice: the Sharara\u2013Zawiya line on 14 August (force majeure at Zawiya, output down a fifth) and the Hamada\u2013Tahara valve on 15 September. Eastern terminals kept loading. Our standing forecast is that another force majeure is more likely than not within six months."], ["Nigeria", "Dangote changes the Atlantic. At 650,000\u2013700,000 b/d the refinery makes Nigeria a net product exporter and cuts European gasoline exports to West Africa. The delta remains the physical risk: the Trans Niger explosion and Rivers State emergency rule in 2025 showed how fast politics and pipelines connect."], ["North African gas", "Algeria is Europe''s reliable southern supplier through Transmed and Medgaz; Libya''s Greenstream is the fragile one. Egypt has flipped from exporter to importer as Zohr declines, and the 2025 Israel\u2013Iran war showed how dependent Cairo is on the Israeli link and on spot LNG."], ["East Africa", "EACOP was 82% built in April 2026 with first oil targeted for late 2026; Mozambique LNG restarted in January after five years, with first cargo in 2029; GTA made Mauritania and Senegal LNG exporters in 2025. These are the new flows, and each depends on a single pipeline or plant."], ["What we are watching", "Hormuz truce negotiations and the US blockade; Red Sea insurance and routing after the October attack; Libya''s Sharara line; EACOP commissioning; and whether Mozambique LNG''s security holds. Open calls on each are on the Forecasts tab."]]'::jsonb),
('S00', '2026-11-02', 'South America baseline: copper, lithium, iron ore and the new Atlantic oil', 'The desk''s starting view on the region''s flows: Andean copper and lithium to Asia, Brazilian ore round the Cape, Vaca Muerta and the Guyana–Suriname basin, and the Caribbean lanes that sanctions reshaped.', '[["Copper", "Chile and Peru supply about 40% of world mine output and the risks are physical and local rather than national: a collapsed sector at El Teniente, a blocked road out of Las Bambas, a permit that takes six years. Panama''s closed mine is the one true policy shock in the region and its restart is a political negotiation. The Anglo\u2013Teck merger consolidates the north Chilean district; Vicu\u00f1a in Argentina is the next large project if RIGI holds."], ["Lithium", "The triangle has three jurisdictions and three models: Chile''s state-partnered contracts, Argentina''s provincial concessions under RIGI, and Bolivia''s state monopoly that still produces almost nothing. Prices are low, so the risk is to project timelines rather than to existing cargo. Watch Bolivia''s legislature and any Chilean move to tender new salars."], ["Iron ore", "Vale moves about 300 Mt/y to China round the Cape; it is the most reliable large flow in this engine, with court-ordered rail stoppages and dam decommissioning as the known interruptions. The US tariff on Brazil mattered more politically than for ore, which flows east."], ["Oil", "Guyana is the growth story, at over 900,000 b/d and rising, with Suriname five years behind. Brazil''s pre-salt is the volume, and the Equatorial Margin well is the option. Argentina''s shale crude exports are growing with Oldelval and will step up when VMOS opens in 2027. Venezuela is the wildcard: after the January 2026 operation, every cargo depends on a licence and the physical system is degraded; treat all Venezuelan data as provisional."], ["Lanes", "The Panama Canal is a water story: 2023\u201324 showed what a drought does to LNG and LPG routing. The Caribbean crude lane now carries interdiction risk for unlicensed liftings. The Magellan route matters for Vaca Muerta crude to the Pacific and for ships too large for the canal."], ["What we are watching", "Peru''s and Colombia''s new governments and Brazil''s post-election cabinet; the Las Bambas road; Cobre Panam\u00e1 talks; OFAC''s Venezuela licences; Gat\u00fan Lake levels from January; and Argentina''s first LNG cargo. Open calls are on the Forecasts tab."]]'::jsonb)
